WITH parsed AS (SELECT id, service, level, latency_ms, status_code, GET_JSON_OBJECT(payload_json, '$.user.id') AS user_id, SIZE(context) AS num_context, ARRAY_CONTAINS(MAP_KEYS(context), 'version') AS has_version, context['version'] AS version FROM app_logs) SELECT *, NTILE(10) OVER (PARTITION BY level ORDER BY status_code ASC, id ASC) AS status_code_bucket, ROW_NUMBER() OVER (PARTITION BY service ORDER BY num_context ASC, id ASC) AS seq_no FROM parsed WHERE service = 'billing';
